import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int[] kn = new int[n + 1]; // 1-based indexing
        for (int i = 1; i <= n; i++) {
            kn[i] = scanner.nextInt();
        }
        // Selection sort
        for (int i = 1; i <= n - 1; i++) {
            int k = i;
            int min = kn[i];
            for (int j = i + 1; j <= n; j++) {
                if (kn[j] < min) {
                    min = kn[j];
                    k = j;
                }
            }
            // Swap kn[k] and kn[i]
            int temp = kn[k];
            kn[k] = kn[i];
            kn[i] = temp;
        }
        System.out.println(kn[(1 + n) / 2]);
        scanner.close();
    }
}
